import statistics as st
import re
def days(s):
    m=re.match(r"(\d+)(h|d|w|mo|y)",s.replace(" ago",""))
    n,u=int(m.group(1)),m.group(2)
    return {"h":n/24,"d":n,"w":7*n,"mo":30*n,"y":365*n}[u]
